            const savedId = localStorage.getItem('selectedCountryId') || sessionStorage.getItem('selectedCountryId');
            if (savedId) {
                const idNum = parseInt(savedId, 10);
                if (idNum === 1 || idNum === 2) return idNum;
            }
            // Check selectedCountry ("in" for India, "ae" for UAE)
            const savedCode = localStorage.getItem('selectedCountry') || sessionStorage.getItem('selectedCountry');
            if (savedCode) {
                const code = String(savedCode).toLowerCase().trim();
                if (code === 'in' || code === 'india') return 1;
                if (code === 'ae' || code === 'uae') return 2;
            }
            // Fallback direct storage keys
            const altKeys = ["country_id", "countryId", "country"];
            for (const key of altKeys) {
                const val = localStorage.getItem(key) || sessionStorage.getItem(key);
                if (val) {
                    const strVal = String(val).trim().toLowerCase();
                    if (strVal === "1" || strVal === "in" || strVal === "india") return 1;
                    if (strVal === "2" || strVal === "ae" || strVal === "uae") return 2;
                }
            }
