        document.getElementById("j-welcome-sub").innerText = widgetConfig.welcomeSubtitle;
        const avatarImg = document.getElementById("j-avatar-img");
        if (avatarImg && widgetConfig.logoUrl) {
            avatarImg.src = widgetConfig.logoUrl;
        }
        const cid = getCountryId();
        let chips = widgetConfig.chips;
        if (!chips || chips.length === 0 || (cid === 1 && chips.some(c => c.toLowerCase().includes("borosil") || c.toLowerCase().includes("shoes")))) {
            chips = getCountryChips(cid);
        } else if (cid === 2 && chips.some(c => c.toLowerCase().includes("dates") || c.toLowerCase().includes("jewellery") || c.toLowerCase().includes("crystal"))) {
            chips = getCountryChips(cid);
        }
        chipsGrid.innerHTML = "";
