    function findAndInvokeReactAddToWishlist(productObj) {
        try {
            if (typeof document === 'undefined') return false;
            const els = document.querySelectorAll('button, a, div, header, main');
            for (let i = 0; i < els.length; i++) {
                const el = els[i];
                const keys = Object.keys(el);
                const fk = keys.find(k => k.startsWith('__reactFiber$') || k.startsWith('__reactContainer$') || k.startsWith('__reactProps$'));
                if (!fk) continue;
                let fiber = el[fk];
                let depth = 0;
                while (fiber && depth < 40) {
                    depth++;
                    if (fiber.memoizedProps && typeof fiber.memoizedProps.addToWishlist === 'function') {
                        fiber.memoizedProps.addToWishlist(productObj);
                        console.log("Widget: Invoked React addToWishlist via memoizedProps!");
                        return true;
                    }
                    if (fiber.dependencies && fiber.dependencies.firstContext) {
                        let ctx = fiber.dependencies.firstContext;
                        while (ctx) {
                            if (ctx.memoizedValue && typeof ctx.memoizedValue.addToWishlist === 'function') {
                                ctx.memoizedValue.addToWishlist(productObj);
                                console.log("Widget: Invoked React addToWishlist via Context!");
                                return true;
                            }
                            ctx = ctx.next;
                        }
                    }
                    fiber = fiber.return || fiber.parent;
                }
            }
        } catch (e) {
            console.warn("Widget: React Fiber wishlist sync attempt", e);
        }
        return false;
    }
