            window.dispatchEvent(new CustomEvent("wishlistUpdated", eventDetail));
            window.dispatchEvent(new CustomEvent("wishlist-updated", eventDetail));
            window.dispatchEvent(new CustomEvent("user_wishlist_updated", eventDetail));
            window.dispatchEvent(new CustomEvent("shopping_wishlist_updated", eventDetail));
