            '[class*="wishlist_badge"]',
            '[id*="wishlist-count"]',
            '[id*="wishlistCount"]',
            'a[href*="/wishlist"] span',
            'a[href*="/wishlist"] .badge',
            '.wishlist-icon-badge',
