        let unitPrice = parseFloat((selectedVariant && selectedVariant.price) || p.price || p.offer_price || "0") || 0;
        let paymentType = 0; // 0 = Cash On Delivery, 1 = Online Payment, 2 = Tabby, 3 = Tamara
        let shippingFee = 20.0;
